import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem99 corrige atribuicao sem alterar identidade ou operacao',()=>{for(const [id,titulo] of [["mlMLB4644707253","Lavadora Alta Pressão Compacta 1400w, 1600psi, 300l/h"],["mlMLB4645102377","Kit Body Splash Masculino Barbarius + Enigma + Midtown 200ml"],["mlMLB4699180013","Tênis Vans Vr3 Ultrarange Marshmallow Slip Meia Unissex"]]){const p={id,titulo,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.notEqual(x.comentario,p.comentario);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,titulo);assert.deepEqual(correctProductData(x),x);}});
